{"lib": "field", "chunk": {"id": "sp-ny-who-1", "state": "NY", "tier": "core", "title": "New York: federal OSHA for private crews, a state plan for public workers", "topic": "State safety plan: who enforces and what differs", "text": "New York has an OSHA-approved State Plan that covers state and local government workers only, according to OSHA's list of State Plans. Private employers there, including a contractor working for a city or a water district, are under federal OSHA: trench protection from 5 ft (29 CFR 1926.652), the construction confined space rule (29 CFR 1926 Subpart AA), fall protection at 6 ft (29 CFR 1926.501), and reporting a death within 8 hours and a hospitalization, amputation or eye loss within 24 hours to federal OSHA at 1-800-321-6742 (29 CFR 1904.39). The city's or district's own employees on the same job are under the state plan. The public-sector plan's rules were not read for this library; it is not confirmed whether they differ from the federal text.", "source": "OSHA State Plans page", "url": "https://www.osha.gov/stateplans", "checked": "2026-11-20", "edition": "OSHA State Plans page, read 2026-11-20", "confidence": "medium", "kind": "summary", "license": "gov-state", "unconfirmed": "yes"}}]$kb$::jsonb) with ordinality t(e, i),
       (select max(ord) as mx from pb_ai.kb_chunks where version = 'b3e91f6c47d2') m
 where not exists (select 1 from pb_ai.kb_chunks k where k.version = 'b3e91f6c47d2' and k.chunk->>'id' = t.e->'chunk'->>'id');

-- the version's row count (the Ask loader refuses a library whose rows don't match kb_versions.n)
update pb_ai.kb_versions v
   set n = c.n, counts = c.counts
  from (select sum(k)::int as n, jsonb_object_agg(lib, k) as counts
          from (select lib, count(*)::int as k from pb_ai.kb_chunks where version = 'b3e91f6c47d2' group by lib) x) c
 where v.version = 'b3e91f6c47d2';
-- drop the saved search index so workers rebuild it from the rows
delete from pb_ai.kb_index_parts where version = 'b3e91f6c47d2';
delete from pb_ai.kb_index where version = 'b3e91f6c47d2';
-- checks: ords must stay 0..n-1 with no gaps, ids unique
do $chk$
declare n int; mx int; d int;
begin
  select count(*), max(ord), count(distinct chunk->>'id') into n, mx, d from pb_ai.kb_chunks where version = 'b3e91f6c47d2';
  if mx <> n - 1 then raise exception 'FAIL ord gap: % rows, max ord %', n, mx; end if;
  if d <> n then raise exception 'FAIL duplicate chunk id: % ids for % rows', d, n; end if;
  if (select v.n from pb_ai.kb_versions v where v.version = 'b3e91f6c47d2') <> n then raise exception 'FAIL kb_versions.n'; end if;
end $chk$;
commit;
